def m(book,ch,kind,ns,parts='*',reason=None):
    return [dict(item_id=f'8227:TB:{book}:C{ch}:{kind}:{n}',parts=parts,
        membership_reason=reason or 'The named source responses require this decision. Connected responses, original scope restrictions and registered source defects remain attached to the source item.')for n in ns]
