def family(slug,title,decision,givens,constraints,rep,scaffold,methods,form,difficulty,distinction,ds,ms,pattern=None,exams=(),reason=None):
    families.append(dict(family_id='8227:TEXTBOOK-FAMILY:'+slug,title=title,learner_decisions=decision,
        givens_and_unknowns=givens,constraints=constraints,representation_and_response=rep,
        scaffolding_and_connected_parts=scaffold,alternative_methods=methods,
        units_and_precision='Exact algebra unless a named source response expressly requests rounding. Physical deviation examples retain degrees Celsius or millimetres. Graph locations and end-point inclusion must agree with the exact solution; the source item retains its own convention.',
        answer_form=form,difficulty_progression=difficulty,distinction_basis=distinction,
        assessed_demand_ids=ds,member_specs=ms,examination_relation=dict(
        kind='structural branch'if pattern else'textbook-only',pattern_ids=['8227:FAMILY:'+pattern]if pattern else[],part_ids=list(exams),
        evidence_label='examination-observed (NSSCAS 8227), comparative link only'if pattern else'textbook-derived',
        reason=reason or 'No complete matching examination structure is established for this supporting textbook task. This is internal textbook-derived evidence; it establishes neither exam frequency nor a standalone recipe.')))

